import { BackendErrorResponse, BackendFieldError } from "../../components/forms/hooks/useBackendErrors";
import type { OptionsTransport } from "../../components/forms/transport/types";
import { API_BASE, SUBMIT_PATH, BASE_HEADERS } from "./constants";

/**
 * Network layer for this form — the ONLY file here that talks to your backend
 * (AI_AGENT_RULES § R-55: component → hooks.ts → services.ts).
 *
 * Generated for axios because this variant was installed with `--axios`.
 * Re-install without the flag to go back to the dependency-free `fetch` version.
 */

/**
 * Normalize any backend payload to AfnoUI's expected shape:
 * { success: false, message: string, errors?: [{ field, message }] }
 *
 * If your API uses a different format, edit only this function.
 */
function normalizeBackendError(data: unknown): BackendErrorResponse {
  if (typeof data !== "object" || data === null) {
    return { success: false, message: "Server error", errors: [] };
  }

  const payload = data as Record<string, unknown>;
  const message =
    (typeof payload.message === "string" && payload.message) ||
    (typeof payload.error === "string" && payload.error) ||
    "Server error";

  let errors: BackendFieldError[] = [];

  // Shape A: { errors: [{ field, message }] }
  if (Array.isArray(payload.errors)) {
    errors = payload.errors
      .map((item) => {
        if (typeof item !== "object" || item === null) return null;
        const e = item as Record<string, unknown>;
        const field = typeof e.field === "string" ? e.field : (typeof e.path === "string" ? e.path : null);
        const text = typeof e.message === "string" ? e.message : null;
        return field && text ? { field, message: text } : null;
      })
      .filter((e): e is BackendFieldError => e !== null);
  }

  // Shape B: { fieldErrors: { email: "Invalid", password: ["Too short"] } }
  if (errors.length === 0 && typeof payload.fieldErrors === "object" && payload.fieldErrors !== null) {
    const map = payload.fieldErrors as Record<string, unknown>;
    errors = Object.entries(map).flatMap(([field, raw]) => {
      if (typeof raw === "string") return [{ field, message: raw }];
      if (Array.isArray(raw)) {
        return raw
          .filter((x): x is string => typeof x === "string" && x.length > 0)
          .map((message) => ({ field, message }));
      }
      return [];
    });
  }

  return { success: false, message, errors };
}

import axios from "axios";

/**
 * Single place the HTTP client is named, so swapping clients (or adding
 * interceptors / auth refresh) is a one-spot change.
 */
async function request(url: string, data: Record<string, unknown>): Promise<void> {
  await axios.post(url, data, { headers: { "Content-Type": "application/json", ...BASE_HEADERS } });
}


/**
 * Adapter that lets the ENGINE's option-loading use axios as well.
 * The page mounts this via `FormTransportProvider`; without it the async /
 * infinite fields would keep using their built-in fetch default.
 */
export const optionsTransport: OptionsTransport = async (request, signal) => {
  const res = await axios.request({
    url: request.url,
    method: request.method,
    headers: { ...BASE_HEADERS, ...request.headers },
    params: request.params,
    data: request.body,
    signal,
  });
  return res.data;
};
export const formService = {
  /**
   * Throws a normalized `BackendErrorResponse` on failure so the hook layer can
   * map it onto field errors. Nothing is swallowed here.
   */
  async submitForm(data: Record<string, unknown>): Promise<void> {
    try {
      await request(`${API_BASE}${SUBMIT_PATH}`, data);
    } catch (error: unknown) {
    if (axios.isAxiosError(error) && error.response?.data !== undefined) {
      throw normalizeBackendError(error.response.data);
    }
    throw { success: false, message: "Network error — please try again", errors: [] } as BackendErrorResponse;
    }
  },
};

import { useMemo } from "react";
import { ReactHookForm } from "../../components/forms/react-hook-form";
import { BackendErrorResponse } from "../../components/forms/hooks/useBackendErrors";
import { useFormSubmit } from "./hooks";
import { FormTransportProvider } from "../../components/forms/transport/context";
import { optionsQueryAdapter } from "./hooks";
import { formConfig } from "./formConfig";
import { formSchema } from "./formSchema";

export default function PaymentForm() {
  const schema = formSchema;

  const { submit } = useFormSubmit();

  const handleSubmit = async (data: Record<string, unknown>) => {
    await submit(data);
  };

  return (
    <div className="container mx-auto py-8 max-w-3xl">
      <FormTransportProvider adapter={optionsQueryAdapter}>
      <ReactHookForm config={formConfig} schema={schema} onSubmit={handleSubmit} />
      </FormTransportProvider>
    </div>
  );
}

/**
 * Tunables for this form.
 *
 * Every knob this variant exposes lives here (AI_AGENT_RULES § R-57), so
 * `hooks.ts` and `services.ts` stay free of magic numbers and you only have
 * one file to edit when a base URL, page size or cache window changes.
 */

/** Base URL every request in services.ts is built from. */
export const API_BASE = "/api";

/** Appended to API_BASE when submitting this form. */
export const SUBMIT_PATH = "/forms/submit";

/** Sent on every request. Add auth headers here. */
export const BASE_HEADERS = {} as Record<string, string>;

/** How long fetched data stays fresh before TanStack Query refetches it. */
export const STALE_TIME_MS = 5 * 60 * 1000;

/** How long unused cache entries are retained before garbage collection. */
export const GC_TIME_MS = 10 * 60 * 1000;

import { useMutation, useQuery, useInfiniteQuery } from "@tanstack/react-query";

import type { OptionsQueryAdapter } from "../../components/forms/transport/types";

import { formService } from "./services";
import { STALE_TIME_MS, GC_TIME_MS } from "./constants";

/**
 * React glue between the form component and `services.ts`.
 *
 * Per AI_AGENT_RULES § R-55 this is the ONLY file that calls services — the
 * page never imports `./services` directly. Submit state, retries and cache
 * invalidation belong here; the request belongs in `services.ts`.
 *
 * Errors are deliberately left to propagate: `formService.submitForm` throws a
 * normalized `BackendErrorResponse`, which the form component already maps onto
 * field errors. Wrap the call in try/catch here if you want different handling
 * (custom error class, status-code mapping, toast).
 *
 * Generated for TanStack Query because this variant was installed with `--tanstack-query`.
 * Re-install without the flag to go back to the dependency-free React-state version.
 */
export function useFormSubmit() {
  const mutation = useMutation({
    mutationFn: (data: Record<string, unknown>) => formService.submitForm(data),
    gcTime: GC_TIME_MS,
  });

  // `mutateAsync` rethrows, so the normalized BackendErrorResponse still
  // reaches the form component exactly as it does without TanStack Query.
  return { submit: mutation.mutateAsync, submitting: mutation.isPending };
}

/**
 * react-query implementation of the engine's option-loading port.
 *
 * MUST stay a module-level constant — its members are called as hooks, so
 * rebuilding it per render would violate the rules of hooks.
 */
export const optionsQueryAdapter: OptionsQueryAdapter = {
  useAsyncQuery({ key, enabled, run }) {
    const { data, isPending, error } = useQuery({
      queryKey: key,
      queryFn: ({ signal }) => run(signal),
      enabled,
      staleTime: STALE_TIME_MS,
      gcTime: GC_TIME_MS,
    });
    return {
      data,
      isLoading: enabled ? isPending : false,
      error: (error as Error | null) ?? null,
    };
  },

  useInfiniteQuery({ key, enabled, run }) {
    const query = useInfiniteQuery({
      queryKey: key,
      queryFn: ({ pageParam, signal }) => run(pageParam as number, signal),
      initialPageParam: 1,
      getNextPageParam: (last) => (last.hasMore ? last.page + 1 : undefined),
      enabled,
      staleTime: STALE_TIME_MS,
      gcTime: GC_TIME_MS,
    });
    return {
      pages: query.data?.pages ?? [],
      isLoading: query.isPending,
      isFetchingNextPage: query.isFetchingNextPage,
      hasNextPage: !!query.hasNextPage,
      fetchNextPage: () => {
        void query.fetchNextPage();
      },
    };
  },
};
